-- checked on the row after the change, for roles that row-level security applies to on the
-- table (not on TG_RELID: on a partition made since the policy was applied, where it is not on yet, this runs too),
-- the row as the table's own; before the update, or after it where the table has a generated column
-- @object trigger "authz_update_after role" ON "ms"."members"
DO $tr$ BEGIN
  IF EXISTS (WITH RECURSIVE t(oid) AS (
               SELECT '"ms"."members"'::pg_catalog.regclass::oid
               UNION ALL SELECT i.inhrelid FROM pg_catalog.pg_inherits i JOIN t ON i.inhparent = t.oid)
             SELECT 1 FROM pg_catalog.pg_attribute a JOIN t ON a.attrelid = t.oid
             WHERE a.attnum > 0 AND NOT a.attisdropped AND a.attgenerated <> '') THEN
    EXECUTE 'CREATE TRIGGER "authz_update_after role" AFTER UPDATE ON "ms"."members" FOR EACH ROW
  WHEN ((OLD."role" IS DISTINCT FROM NEW."role")
    AND pg_catalog.row_security_active(''"ms"."members"''::pg_catalog.regclass)
    AND NOT authz_int."ms.members:column role after:holds"(pg_catalog.jsonb_populate_record(NULL::"ms"."members", pg_catalog.to_jsonb(NEW))))
  EXECUTE FUNCTION authz_int."ms.members:column role after"()';
  ELSE
    EXECUTE 'CREATE TRIGGER "authz_update_after role" BEFORE UPDATE ON "ms"."members" FOR EACH ROW
  WHEN ((OLD."role" IS DISTINCT FROM NEW."role")
    AND pg_catalog.row_security_active(''"ms"."members"''::pg_catalog.regclass)
    AND NOT authz_int."ms.members:column role after:holds"(pg_catalog.jsonb_populate_record(NULL::"ms"."members", pg_catalog.to_jsonb(NEW))))
  EXECUTE FUNCTION authz_int."ms.members:column role after"()';
  END IF;
END $tr$;

-- On a partitioned table, an update that puts a row in another partition is a delete there and an insert here:
-- Postgres runs no AFTER UPDATE row trigger for it. Where the rule's trigger runs after the update, the rule is
-- asked again when the statement is done, of each row it left with other values in these columns than the row that
-- had its key (a key the update made: than the one key it left without a row, or, where that isn't one for one,
-- whatever changed). A trigger before the update has asked it of every row already
CREATE FUNCTION authz_int."ms.members:column role after:moved"() RETURNS trigger
LANGUAGE plpgsql SET search_path FROM CURRENT AS $f$
DECLARE v_lines text; v_row "ms"."members"; v_one boolean; v_virtual text;
BEGIN
  IF NOT pg_catalog.row_security_active('"ms"."members"'::pg_catalog.regclass) THEN RETURN NULL; END IF;
  -- (tgtype's bit 2: before. Asked unless a trigger before the update is there, and on: without one, never less)
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_trigger g WHERE g.tgrelid = '"ms"."members"'::pg_catalog.regclass AND g.tgname = 'authz_update_after role'
             AND g.tgtype & 2 <> 0 AND g.tgenabled <> 'D') THEN
    RETURN NULL;
  END IF;
  -- (PostgreSQL 18: each row with its virtual generated columns, which the statement's rows don't hold)
  SELECT pg_catalog.string_agg(pg_catalog.format('%L, (%s)', a.attname, pg_catalog.pg_get_expr(d.adbin, d.adrelid)), ', ')
      INTO v_virtual FROM pg_catalog.pg_attribute a
      JOIN pg_catalog.pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum
      WHERE a.attrelid = '"ms"."members"'::pg_catalog.regclass AND a.attnum > 0 AND NOT a.attisdropped AND a.attgenerated = 'v';
  v_one := (SELECT count(*) FROM old_rows o WHERE NOT EXISTS (SELECT 1 FROM new_rows n WHERE ROW(n."chat_id"::bigint, n."user_id"::uuid)::text = ROW(o."chat_id"::bigint, o."user_id"::uuid)::text)) = 1
       AND (SELECT count(*) FROM new_rows n WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE ROW(o."chat_id"::bigint, o."user_id"::uuid)::text = ROW(n."chat_id"::bigint, n."user_id"::uuid)::text)) = 1;
  FOR v_row IN
    SELECT (pg_catalog.jsonb_populate_record(NULL::"ms"."members", pg_catalog.to_jsonb(n))).* FROM new_rows n
    WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE ROW(o."chat_id"::bigint, o."user_id"::uuid)::text = ROW(n."chat_id"::bigint, n."user_id"::uuid)::text AND o."role" IS NOT DISTINCT FROM n."role")
      AND NOT (v_one AND NOT EXISTS (SELECT 1 FROM old_rows o WHERE ROW(o."chat_id"::bigint, o."user_id"::uuid)::text = ROW(n."chat_id"::bigint, n."user_id"::uuid)::text)
               AND EXISTS (SELECT 1 FROM old_rows o WHERE o."role" IS NOT DISTINCT FROM n."role"
                           AND NOT EXISTS (SELECT 1 FROM new_rows m WHERE ROW(m."chat_id"::bigint, m."user_id"::uuid)::text = ROW(o."chat_id"::bigint, o."user_id"::uuid)::text)))
  LOOP
    IF v_virtual IS NOT NULL THEN
      EXECUTE 'SELECT (pg_catalog.jsonb_populate_record($1, pg_catalog.jsonb_build_object(' || v_virtual
        || '))).* FROM (SELECT ($1).*) AS r' INTO v_row USING v_row;
    END IF;
    IF NOT (authz_gen."ms.members:column role after:items"(v_row))[1] THEN
      BEGIN
        v_lines := (SELECT string_agg(l, E'\n') FROM authz_gen."ms.members:column role after:why"(v_row) l);
      EXCEPTION WHEN OTHERS THEN
        v_lines := 'no explanation: ' || SQLERRM;
      END;
      RAISE EXCEPTION 'changing role of ms.members % needs: {role <> ''owner''}', ROW(v_row."chat_id"::bigint, v_row."user_id"::uuid)::text USING ERRCODE = 'insufficient_privilege', DETAIL = v_lines,
        SCHEMA = 'ms', TABLE = 'members', CONSTRAINT = 'authz_update', HINT = 'rowstile help AZ709';
    END IF;
  END LOOP;
  RETURN NULL;
END $f$;

-- @object trigger "authz_update_after_moved role" ON "ms"."members"
-- @if partitioned
DO $tr$ BEGIN
  IF (SELECT relkind FROM pg_catalog.pg_class WHERE oid = '"ms"."members"'::regclass) = 'p' THEN
    EXECUTE 'CREATE TRIGGER "authz_update_after_moved role" AFTER UPDATE ON "ms"."members" REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."ms.members:column role after:moved"()';
  END IF;
END $tr$;

