  EXECUTE FUNCTION authz_int."ms.messages:column deleted after"()';
  END IF;
END $tr$;

-- On a partitioned table, an update that puts a row in another partition is a delete there and an insert here:
-- Postgres runs no AFTER UPDATE row trigger for it. Where the rule's trigger runs after the update, the rule is
-- asked again when the statement is done, of each row it left with other values in these columns than the row that
-- had its key (a key the update made: than the one key it left without a row, or, where that isn't one for one,
-- whatever changed). A trigger before the update has asked it of every row already
CREATE FUNCTION authz_int."ms.messages:column deleted after:moved"() RETURNS trigger
LANGUAGE plpgsql SET search_path FROM CURRENT AS $f$
DECLARE v_lines text; v_row "ms"."messages"; v_one boolean; v_virtual text;
BEGIN
  IF NOT pg_catalog.row_security_active('"ms"."messages"'::pg_catalog.regclass) THEN RETURN NULL; END IF;
  -- (tgtype's bit 2: before. Asked unless a trigger before the update is there, and on: without one, never less)
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_trigger g WHERE g.tgrelid = '"ms"."messages"'::pg_catalog.regclass AND g.tgname = 'authz_update_after deleted'
             AND g.tgtype & 2 <> 0 AND g.tgenabled <> 'D') THEN
    RETURN NULL;
  END IF;
  -- (PostgreSQL 18: each row with its virtual generated columns, which the statement's rows don't hold)
  SELECT pg_catalog.string_agg(pg_catalog.format('%L, (%s)', a.attname, pg_catalog.pg_get_expr(d.adbin, d.adrelid)), ', ')
      INTO v_virtual FROM pg_catalog.pg_attribute a
      JOIN pg_catalog.pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum
      WHERE a.attrelid = '"ms"."messages"'::pg_catalog.regclass AND a.attnum > 0 AND NOT a.attisdropped AND a.attgenerated = 'v';
  v_one := (SELECT count(*) FROM old_rows o WHERE NOT EXISTS (SELECT 1 FROM new_rows n WHERE ROW(n."chat_id"::bigint, n."seq"::bigint)::text = ROW(o."chat_id"::bigint, o."seq"::bigint)::text)) = 1
       AND (SELECT count(*) FROM new_rows n WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE ROW(o."chat_id"::bigint, o."seq"::bigint)::text = ROW(n."chat_id"::bigint, n."seq"::bigint)::text)) = 1;
  FOR v_row IN
    SELECT (pg_catalog.jsonb_populate_record(NULL::"ms"."messages", pg_catalog.to_jsonb(n))).* FROM new_rows n
    WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE ROW(o."chat_id"::bigint, o."seq"::bigint)::text = ROW(n."chat_id"::bigint, n."seq"::bigint)::text AND o."deleted" IS NOT DISTINCT FROM n."deleted")
      AND NOT (v_one AND NOT EXISTS (SELECT 1 FROM old_rows o WHERE ROW(o."chat_id"::bigint, o."seq"::bigint)::text = ROW(n."chat_id"::bigint, n."seq"::bigint)::text)
               AND EXISTS (SELECT 1 FROM old_rows o WHERE o."deleted" IS NOT DISTINCT FROM n."deleted"
                           AND NOT EXISTS (SELECT 1 FROM new_rows m WHERE ROW(m."chat_id"::bigint, m."seq"::bigint)::text = ROW(o."chat_id"::bigint, o."seq"::bigint)::text)))
  LOOP
    IF v_virtual IS NOT NULL THEN
      EXECUTE 'SELECT (pg_catalog.jsonb_populate_record($1, pg_catalog.jsonb_build_object(' || v_virtual
        || '))).* FROM (SELECT ($1).*) AS r' INTO v_row USING v_row;
    END IF;
    IF NOT (authz_gen."ms.messages:column deleted after:items"(v_row))[1] THEN
      BEGIN
        v_lines := (SELECT string_agg(l, E'\n') FROM authz_gen."ms.messages:column deleted after:why"(v_row) l);
      EXCEPTION WHEN OTHERS THEN
        v_lines := 'no explanation: ' || SQLERRM;
      END;
      RAISE EXCEPTION 'changing deleted of ms.messages % needs: {deleted and body = ''''}', ROW(v_row."chat_id"::bigint, v_row."seq"::bigint)::text USING ERRCODE = 'insufficient_privilege', DETAIL = v_lines,
        SCHEMA = 'ms', TABLE = 'messages', CONSTRAINT = 'authz_update', HINT = 'rowstile help AZ709';
    END IF;
  END LOOP;
  RETURN NULL;
END $f$;

-- @object trigger "authz_update_after_moved deleted" ON "ms"."messages"
-- @if partitioned
DO $tr$ BEGIN
  IF (SELECT relkind FROM pg_catalog.pg_class WHERE oid = '"ms"."messages"'::regclass) = 'p' THEN
    EXECUTE 'CREATE TRIGGER "authz_update_after_moved deleted" AFTER UPDATE ON "ms"."messages" REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."ms.messages:column deleted after:moved"()';
  END IF;
END $tr$;

