      || '))).* FROM (SELECT ($1).*) AS r' INTO v_row USING v_row;
  END IF;
  BEGIN
    v_lines := (SELECT string_agg(l, E'\n') FROM authz_gen."ms.messages:column edited_at:why"(v_row) l);
  EXCEPTION WHEN OTHERS THEN
