      severity := 'error'; object := r.tbl::text;
      problem := format('%s may TRUNCATE it, which skips row-level security: REVOKE TRUNCATE ON %s FROM %s', 'ms_app', r.tbl, 'ms_app');
      RETURN NEXT;
    END IF;
