           LEFT JOIN pg_description d ON d.objoid = p.oid AND d.classoid = 'pg_policy'::regclass
           WHERE p.polrelid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"ms"."blocks"', '"ms"."bots"', '"ms"."chat_bots"', '"ms"."chats"', '"ms"."members"', '"ms"."messages"', '"ms"."users"']::text[]) x)
             AND coalesce(d.description, '') NOT IN ('rowstile')
