      RETURN NEXT;
    END IF;
    IF has_table_privilege(v_role, r.part, 'TRIGGER') THEN
      severity := 'error'; object := r.part::text;
      problem := format('is a partition of %s (or inherits from it), and %s may make triggers on it (TRIGGER, which GRANT ALL gives): a foreign key''s action that writes its rows runs their functions as the table''s owner, whom no rule holds: REVOKE TRIGGER ON %s FROM %s', r.tbl, 'ms_app', r.part, 'ms_app');
